import "./list-expansion.css";
import { useState, useRef } from "react";

function ListWithAnimation() {
  const [selected, setSelected] = useState<Item | null>(
    null,
  );
  const containerRef = useRef<HTMLDivElement>(null);

  return (
    <div ref={containerRef} className="list-container">
      <div
        className={`view ${selected ? "view--hidden" : "view--visible"}`}
      >
        {items.map((item) => (
          <ListItem
            key={item.id}
            item={item}
            onSelect={setSelected}
          />
        ))}
      </div>

      <div
        className={`view ${selected ? "view--visible" : "view--hidden"}`}
      >
        {selected && (
          <DetailView
            item={selected}
            onBack={() => setSelected(null)}
          />
        )}
      </div>
    </div>
  );
}

.list-container {
  position: relative;
}

.view {
  transition: opacity 100ms ease-out;
}

.view--visible {
  opacity: 1;
}

.view--hidden {
  opacity: 0;
  pointer-events: none;
  position: absolute;
  inset: 0;
}
